-- Schema del registro, separato dalle tabelle Supabase Auth.
-- Accesso soltanto dal backend PostgreSQL; nessuna policy per chiavi pubbliche.
BEGIN;
CREATE SCHEMA IF NOT EXISTS keynes;
SET LOCAL search_path = keynes, pg_catalog;

    CREATE TABLE IF NOT EXISTS crews (id INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, name TEXT NOT NULL, class_code TEXT NOT NULL, flag TEXT NOT NULL DEFAULT 'skull');
    CREATE TABLE IF NOT EXISTS users (id INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, email TEXT NOT NULL UNIQUE, salt TEXT NOT NULL, password_hash TEXT NOT NULL, first_name TEXT NOT NULL, last_name TEXT NOT NULL, class_code TEXT NOT NULL, role TEXT NOT NULL DEFAULT 'student', crew_id INTEGER REFERENCES crews(id), roles TEXT NOT NULL DEFAULT 'Equipaggio', last_password_change TEXT NOT NULL DEFAULT to_char(timezone('UTC', CURRENT_TIMESTAMP), 'YYYY-MM-DD HH24:MI:SS'));
    CREATE TABLE IF NOT EXISTS sessions (token_hash TEXT PRIMARY KEY, user_id INTEGER NOT NULL REFERENCES users(id) ON DELETE CASCADE, expires_at BIGINT NOT NULL);
    CREATE TABLE IF NOT EXISTS reset_tokens (token_hash TEXT PRIMARY KEY, user_id INTEGER NOT NULL REFERENCES users(id) ON DELETE CASCADE, expires_at BIGINT NOT NULL);
    CREATE TABLE IF NOT EXISTS routes (id INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, class_code TEXT NOT NULL, year INTEGER NOT NULL, year_name TEXT NOT NULL, ordinal INTEGER NOT NULL, name TEXT NOT NULL, start_date TEXT NOT NULL DEFAULT '', end_date TEXT NOT NULL DEFAULT '', UNIQUE(class_code,year,ordinal));
    CREATE TABLE IF NOT EXISTS islands (id INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, route_id INTEGER NOT NULL REFERENCES routes(id) ON DELETE CASCADE, name TEXT NOT NULL, topic TEXT NOT NULL);
    CREATE TABLE IF NOT EXISTS daily (id INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, date TEXT NOT NULL, user_id INTEGER NOT NULL REFERENCES users(id) ON DELETE CASCADE, subject TEXT NOT NULL DEFAULT '', presence TEXT NOT NULL DEFAULT 'P', phone TEXT NOT NULL DEFAULT '+', bug INTEGER NOT NULL DEFAULT 0, anxiety INTEGER NOT NULL DEFAULT 0, mystery INTEGER NOT NULL DEFAULT 0, weapon TEXT NOT NULL DEFAULT '', multiverse TEXT NOT NULL DEFAULT '', multiverse_points INTEGER NOT NULL DEFAULT 0, fruit_points INTEGER NOT NULL DEFAULT 0, fruit_note TEXT NOT NULL DEFAULT '', updated_at TEXT NOT NULL DEFAULT to_char(timezone('UTC', CURRENT_TIMESTAMP), 'YYYY-MM-DD HH24:MI:SS'), UNIQUE(date,user_id,subject));
    CREATE TABLE IF NOT EXISTS grades (id INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, user_id INTEGER NOT NULL REFERENCES users(id) ON DELETE CASCADE, date TEXT NOT NULL, type TEXT NOT NULL, grade DOUBLE PRECISION NOT NULL, points INTEGER NOT NULL);
    CREATE TABLE IF NOT EXISTS point_events (id INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, user_id INTEGER NOT NULL REFERENCES users(id) ON DELETE CASCADE, date TEXT NOT NULL, route INTEGER NOT NULL DEFAULT 0, type TEXT NOT NULL, points DOUBLE PRECISION NOT NULL, grade DOUBLE PRECISION, source TEXT NOT NULL, source_row INTEGER NOT NULL, imported_at TEXT NOT NULL DEFAULT to_char(timezone('UTC', CURRENT_TIMESTAMP), 'YYYY-MM-DD HH24:MI:SS'), UNIQUE(source,source_row));
    CREATE INDEX IF NOT EXISTS point_events_user_date ON point_events(user_id,date);
    CREATE TABLE IF NOT EXISTS dreams (id INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, user_id INTEGER NOT NULL REFERENCES users(id) ON DELETE CASCADE, text TEXT NOT NULL);
    CREATE TABLE IF NOT EXISTS mysteries (id INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, title TEXT NOT NULL, description TEXT NOT NULL, revealed INTEGER NOT NULL DEFAULT 0, clues TEXT NOT NULL DEFAULT '[false,false,false,false]');
    CREATE TABLE IF NOT EXISTS imported_rows (id INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, sheet TEXT NOT NULL, data TEXT NOT NULL, imported_at TEXT NOT NULL DEFAULT to_char(timezone('UTC', CURRENT_TIMESTAMP), 'YYYY-MM-DD HH24:MI:SS'));
  
ALTER TABLE grades ADD COLUMN IF NOT EXISTS subject TEXT NOT NULL DEFAULT '';
ALTER TABLE point_events ADD COLUMN IF NOT EXISTS subject TEXT NOT NULL DEFAULT '';
ALTER TABLE keynes.crews ENABLE ROW LEVEL SECURITY;
ALTER TABLE keynes.users ENABLE ROW LEVEL SECURITY;
ALTER TABLE keynes.sessions ENABLE ROW LEVEL SECURITY;
ALTER TABLE keynes.reset_tokens ENABLE ROW LEVEL SECURITY;
ALTER TABLE keynes.routes ENABLE ROW LEVEL SECURITY;
ALTER TABLE keynes.islands ENABLE ROW LEVEL SECURITY;
ALTER TABLE keynes.daily ENABLE ROW LEVEL SECURITY;
ALTER TABLE keynes.grades ENABLE ROW LEVEL SECURITY;
ALTER TABLE keynes.point_events ENABLE ROW LEVEL SECURITY;
ALTER TABLE keynes.dreams ENABLE ROW LEVEL SECURITY;
ALTER TABLE keynes.mysteries ENABLE ROW LEVEL SECURITY;
ALTER TABLE keynes.imported_rows ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON SCHEMA keynes FROM PUBLIC;
REVOKE ALL ON ALL TABLES IN SCHEMA keynes FROM PUBLIC;
COMMIT;
